javascript:
frappe.query_reports["متابعة تحصيل الإيجارات"] = {
    filters: [
        {
            fieldname: "company",
            label: "الشركة",
            fieldtype: "Link",
            options: "Company",
            default: "OSUS",
            reqd: 1
        },
        {
            fieldname: "as_of_date",
            label: "حتى تاريخ",
            fieldtype: "Date",
            default: frappe.datetime.get_today(),
            reqd: 1
        },
        {
            fieldname: "building",
            label: "المبنى",
            fieldtype: "Link",
            options: "Item",
            get_query: function () {
                return {
                    filters: {
                        item_group: "building",
                        has_variants: 1,
                        disabled: 0
                    }
                };
            }
        }
    ],

    onload: function (report) {
        $(report.page.wrapper).addClass("osus-rent-report");

        if (!document.getElementById("osus-rent-report-style")) {
            const style = document.createElement("style");
            style.id = "osus-rent-report-style";
            style.textContent = `
                .osus-rent-report .datatable .dt-header,
                .osus-rent-report .datatable .dt-header .dt-row,
                .osus-rent-report .datatable .dt-header .dt-cell,
                .osus-rent-report .datatable .dt-header .dt-cell__content {
                    background-color: #e9f2ee !important;
                    color: #17654c !important;
                    font-weight: 700 !important;
                }

                .osus-rent-report .datatable .dt-row .dt-cell {
                    transition: background-color 180ms ease, color 180ms ease;
                }

                .osus-rent-report .datatable .dt-row:hover .dt-cell {
                    background-color: #e5f5ed !important;
                }

                .osus-rent-report .datatable .dt-row:active .dt-cell {
                    background-color: #c9ead9 !important;
                }

                .osus-rent-report .datatable .dt-row:hover a {
                    color: #087c58 !important;
                    text-decoration: underline;
                }
            `;
            document.head.appendChild(style);
        }

        if (!report.get_filter_value("as_of_date")) {
            report.set_filter_value("as_of_date", frappe.datetime.get_today());
        }
    }
};

report_script:
filters = filters or {}

company = filters.get("company")
as_of = frappe.utils.getdate(
    filters.get("as_of_date") or frappe.utils.today()
)
building_filter = filters.get("building")

if not company:
    frappe.throw("اختر الشركة أولًا.")

currency = frappe.db.get_value(
    "Company", company, "default_currency"
)

columns = [
    {
        "label": "العقد",
        "fieldname": "lease",
        "fieldtype": "Link",
        "options": "Subscription",
        "width": 200
    },
    {
        "label": "المبنى",
        "fieldname": "building",
        "fieldtype": "Data",
        "width": 100
    },
    {
        "label": "الوحدة",
        "fieldname": "unit",
        "fieldtype": "Data",
        "width": 180
    },
    {
        "label": "المستأجر",
        "fieldname": "tenant",
        "fieldtype": "Link",
        "options": "Customer",
        "width": 160
    },
    {
        "label": "بداية العقد",
        "fieldname": "start_date",
        "fieldtype": "Date",
        "width": 115
    },
    {
        "label": "نهاية العقد",
        "fieldname": "end_date",
        "fieldtype": "Date",
        "width": 115
    },
    {
        "label": "قيمة إيجار العقد",
        "fieldname": "contract_value",
        "fieldtype": "Currency",
        "options": "currency",
        "width": 150
    },
    {
        "label": "المستحق حتى التاريخ",
        "fieldname": "due",
        "fieldtype": "Currency",
        "options": "currency",
        "width": 160
    },
    {
        "label": "المحصّل للإيجار",
        "fieldname": "collected",
        "fieldtype": "Currency",
        "options": "currency",
        "width": 145
    },
    {
        "label": "باقي قيمة العقد",
        "fieldname": "remaining",
        "fieldtype": "Currency",
        "options": "currency",
        "width": 145
    },
    {
        "label": "الإيجار المتأخر",
        "fieldname": "overdue",
        "fieldtype": "Currency",
        "options": "currency",
        "width": 145
    },
    {
        "label": "الحالة",
        "fieldname": "collection_status",
        "fieldtype": "Data",
        "width": 160
    },
    {
        "label": "العملة",
        "fieldname": "currency",
        "fieldtype": "Link",
        "options": "Currency",
        "hidden": 1
    }
]

result = []

# العقود التي تسمح صلاحيات المستخدم بقراءتها
leases = frappe.get_list(
    "Subscription",
    filters={
        "company": company,
        "party_type": "Customer",
        "docstatus": ["!=", 2],
        "status": ["!=", "Cancelled"]
    },
    fields=["name"],
    order_by="start_date asc, name asc",
    limit_page_length=0
)

for lease_row in leases:
    lease = frappe.get_doc("Subscription", lease_row.name)
    lease.check_permission("read")

    unit_names = []
    building_names = []
    rent_items = []
    monthly_rent = 0
    issue = ""

    # الوحدات والمباني وقيمة الإيجار الشهري
    for plan_row in lease.get("plans") or []:
        plan = frappe.get_doc(
            "Subscription Plan", plan_row.plan
        )
        plan.check_permission("read")

        unit = plan.get("item")

        if unit:
            if unit not in unit_names:
                unit_names.append(unit)

            if unit not in rent_items:
                rent_items.append(unit)

            building = frappe.db.get_value(
                "Item", unit, "variant_of"
            ) or plan.get("custom_building")

            if building and building not in building_names:
                building_names.append(building)

        if (
            plan.billing_interval != "Month"
            or frappe.utils.cint(
                plan.billing_interval_count
            ) != 1
            or plan.price_determination != "Fixed Rate"
        ):
            issue = "راجع إعداد خطة الإيجار"

        if plan.currency != currency:
            issue = "عملة الخطة تختلف عن الشركة"

        qty = frappe.utils.flt(plan_row.qty)
        rate = frappe.utils.flt(plan.cost)

        if qty <= 0 or rate <= 0:
            issue = "راجع السعر أو الكمية"

        monthly_rent = monthly_rent + rate * qty

    if building_filter and building_filter not in building_names:
        continue

    record = {
        "lease": lease.name,
        "building": "، ".join(building_names),
        "unit": "، ".join(unit_names),
        "tenant": lease.party,
        "start_date": lease.start_date,
        "end_date": lease.end_date,
        "currency": currency,
        "contract_value": None,
        "due": None,
        "collected": None,
        "remaining": None,
        "overdue": None,
        "collection_status": ""
    }

    if not lease.start_date or not lease.end_date:
        issue = "استكمل تاريخي العقد"

    if not rent_items:
        issue = "لا توجد وحدة مرتبطة بخطة"

    if lease.get("follow_calendar_months"):
        issue = "راجع احتساب الأشهر التقويمية"

    if (
        frappe.utils.flt(
            lease.get("additional_discount_percentage")
        )
        or frappe.utils.flt(
            lease.get("additional_discount_amount")
        )
    ):
        issue = "يلزم احتساب خصم العقد"

    lease_currency = lease.get("custom_settlement_currency")

    if lease_currency and lease_currency != currency:
        issue = "عملة العقد تختلف عن الشركة"

    if issue:
        record["collection_status"] = issue
        result.append(record)
        continue

    start = frappe.utils.getdate(lease.start_date)
    end = frappe.utils.getdate(lease.end_date)

    if end < start:
        record["collection_status"] = "راجع تاريخ نهاية العقد"
        result.append(record)
        continue

    # كل قسط يستحق في بداية الشهر الإيجاري
    end_exclusive = frappe.utils.getdate(
        frappe.utils.add_days(end, 1)
    )

    period_count = 0
    due_count = 0
    period_start = start

    while period_start < end_exclusive:
        if period_count >= 1200:
            issue = "مدة العقد تتجاوز الحد المدعوم"
            break

        next_start = frappe.utils.getdate(
            frappe.utils.add_months(
                start, period_count + 1
            )
        )

        if next_start > end_exclusive:
            issue = "العقد يتضمن جزء شهر؛ يلزم مراجعته"
            break

        if period_start <= as_of:
            due_count = due_count + 1

        period_count = period_count + 1
        period_start = next_start

    if issue:
        record["collection_status"] = issue
        result.append(record)
        continue

    contract_value = frappe.utils.flt(
        monthly_rent * period_count, 2
    )
    due = frappe.utils.flt(
        monthly_rent * due_count, 2
    )

    # الفواتير المعتمدة المرتبطة بالعقد
    invoice_rows = frappe.get_all(
        "Sales Invoice",
        filters={
            "subscription": lease.name,
            "company": company,
            "customer": lease.party,
            "docstatus": 1,
            "is_return": 0
        },
        fields=["name"],
        limit_page_length=0
    )

    invoice_ids = []
    rent_by_invoice = {}
    total_by_invoice = {}

    for invoice_row in invoice_rows:
        invoice = frappe.get_doc(
            "Sales Invoice", invoice_row.name
        )
        invoice.check_permission("read")

        if invoice.currency != currency:
            frappe.throw(
                "عملة الفاتورة تختلف عن الشركة: "
                + invoice.name
            )

        rent_amount = 0

        for line in invoice.get("items") or []:
            if (
                line.item_code in rent_items
                and not line.get(
                    "custom_lease_charge_reference"
                )
            ):
                rent_amount = (
                    rent_amount
                    + frappe.utils.flt(line.net_amount)
                )

        if invoice.get("disable_rounded_total"):
            invoice_total = frappe.utils.flt(
                invoice.grand_total
            )
        else:
            invoice_total = frappe.utils.flt(
                invoice.rounded_total
                or invoice.grand_total
            )

        if rent_amount > 0:
            if (
                invoice_total <= 0
                or rent_amount > invoice_total + 0.01
            ):
                frappe.throw(
                    "راجع توزيع الإيجار على الفاتورة: "
                    + invoice.name
                )

            invoice_ids.append(invoice.name)
            rent_by_invoice[invoice.name] = rent_amount
            total_by_invoice[invoice.name] = invoice_total

    # سندات القبض المرتبطة بفواتير العقد
    candidate_names = []

    if invoice_ids:
        references = frappe.get_all(
            "Payment Entry Reference",
            filters={
                "parenttype": "Payment Entry",
                "parentfield": "references",
                "reference_doctype": "Sales Invoice",
                "reference_name": ["in", invoice_ids],
                "allocated_amount": [">", 0]
            },
            fields=["parent"],
            limit_page_length=0
        )

        for reference in references:
            if reference.parent not in candidate_names:
                candidate_names.append(reference.parent)

    # مقدم الإيجار والسندات المرتبطة مباشرة بالعقد
    direct_payments = frappe.get_all(
        "Payment Entry",
        filters={
            "custom_residential_lease": lease.name,
            "custom_lease_payment_purpose": [
                "in", ["Rent Advance", "Rent Payment"]
            ],
            "company": company,
            "party_type": "Customer",
            "party": lease.party,
            "payment_type": "Receive",
            "docstatus": 1,
            "posting_date": ["<=", str(as_of)]
        },
        fields=["name"],
        limit_page_length=0
    )

    for payment_row in direct_payments:
        if payment_row.name not in candidate_names:
            candidate_names.append(payment_row.name)

    collected = 0

    for payment_name in candidate_names:
        payment = frappe.get_doc(
            "Payment Entry", payment_name
        )

        if (
            payment.docstatus != 1
            or payment.payment_type != "Receive"
            or frappe.utils.getdate(
                payment.posting_date
            ) > as_of
        ):
            continue

        payment.check_permission("read")

        if (
            payment.company != company
            or payment.party_type != "Customer"
            or payment.party != lease.party
        ):
            frappe.throw(
                "بيانات سند القبض تختلف عن العقد: "
                + payment.name
            )

        if (
            payment.paid_from_account_currency != currency
            or payment.paid_to_account_currency != currency
        ):
            frappe.throw(
                "عملة سند القبض تختلف عن الشركة: "
                + payment.name
            )

        # توزيع القبض بين الإيجار والخدمات بنسبة الفاتورة
        for reference in payment.get("references") or []:
            invoice_name = reference.reference_name

            if (
                reference.reference_doctype
                == "Sales Invoice"
                and invoice_name in rent_by_invoice
            ):
                allocated = frappe.utils.flt(
                    reference.allocated_amount
                )

                if allocated > 0:
                    collected = collected + (
                        allocated
                        * rent_by_invoice[invoice_name]
                        / total_by_invoice[invoice_name]
                    )

        # الجزء غير المخصص من مقدم الإيجار فقط
        if (
            payment.get("custom_residential_lease")
            == lease.name
            and payment.get("custom_lease_payment_purpose")
            in ["Rent Advance", "Rent Payment"]
        ):
            unallocated = frappe.utils.flt(
                payment.unallocated_amount
            )

            if unallocated > 0:
                collected = collected + unallocated

    collected = frappe.utils.flt(collected, 2)
    remaining = frappe.utils.flt(
        contract_value - collected, 2
    )
    overdue = max(
        frappe.utils.flt(due - collected, 2), 0
    )

    if as_of < start:
        collection_status = "لم يبدأ الاستحقاق"
    elif overdue > 0 and collected > 0:
        collection_status = "سداد جزئي — متأخر"
    elif overdue > 0:
        collection_status = "متأخر"
    elif collected > due:
        collection_status = "مسدد مع مقدم إيجار"
    else:
        collection_status = "مسدد حتى التاريخ"

    record.update({
        "contract_value": contract_value,
        "due": due,
        "collected": collected,
        "remaining": remaining,
        "overdue": overdue,
        "collection_status": collection_status
    })

    result.append(record)

data = columns, result
